"use client"
import { useState } from "react"
import { motion, AnimatePresence } from "framer-motion"
import Nav from "./ui/nav";
import { NavButton } from "./ui/button";

interface SideMenuProps {
    cardColor?: string;
    cardImage?: string;
    imageOpacity?: number;
    imageSaturation?: number;
    links?: { title: string, href: string }[];
    footerLinks?: { title: string, href: string }[];
}

export default function SideMenu({ 
    cardColor = '#c9fd74', 
    cardImage, 
    imageOpacity = 1,
    imageSaturation = 1,
    links, 
    footerLinks 
}: SideMenuProps) {
    const [isActive, setIsActive] = useState(false)

    const variants = {
        open: {
            width: 400,
            height: 'fit-content',
            backgroundColor: cardImage ? 'transparent' : cardColor,
            borderRadius: '20px',
            transition: {
                duration: 0.6,
                ease: [0.76, 0, 0.24, 1]
            },
            top: -5,
            right: -5,
        },
        closed: {
            width: '80px',
            height: '30px',
            backgroundColor: 'rgba(0, 0, 0, 0)',
            borderRadius: '20px',
            transition: {
                duration: 0.7,
                ease: [0.76, 0, 0.24, 1]
            },
            top: 0,
            right: 0,
        }
    }

    return (
        <div className="absolute top-2 right-2 lg:top-5 lg:right-5 scale-85 md:scale-100 origin-top-right">
            <motion.div
                className="relative sm:w-full"
                variants={variants}
                initial="closed"
                animate={isActive ? "open" : "closed"}
                transition={{ duration: 0.4, ease: [0.76, 0, 0.24, 1] }}
            >
                {cardImage && (
                    <div 
                        className="absolute inset-0 rounded-[20px] overflow-hidden"
                        style={{
                            backgroundImage: `url(${cardImage})`,
                            backgroundSize: 'cover',
                            backgroundPosition: 'center',
                            backgroundRepeat: 'no-repeat',
                            opacity: imageOpacity,
                            filter: `saturate(${imageSaturation})`,
                        }}
                    />
                )}
                <div className="relative z-10">
                    <AnimatePresence mode="wait">
                        {isActive && (
                            <motion.div
                                key="nav"
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                exit={{ opacity: 0 }}
                                transition={{ delay: 0.1 }}
                            >
                                <Nav links={links} footerLinks={footerLinks} />
                            </motion.div>
                        )}
                    </AnimatePresence>
                    <NavButton isActive={isActive} setIsActive={setIsActive} menuBgColor={cardColor} menuBgImage={cardImage} />
                </div>
            </motion.div>
        </div>
    )
}

"use client";

import React from "react";
import { motion } from "framer-motion";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

// Button Variants for Styling
const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm/6 font-medium transition-all disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground shadow-xs hover:bg-primary/90",
        destructive: "bg-destructive text-white shadow-xs hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
        outline: "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:bg-input/30 dark:border-input dark:hover:bg-input/50",
        secondary: "bg-secondary text-secondary-foreground shadow-xs hover:bg-secondary/80",
        ghost: "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        sm: "h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

// Generic Button Component
interface ButtonProps extends React.ComponentProps<"button">, VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

export function Button({ className, variant, size, asChild = false, ...props }: ButtonProps) {
  const Comp = asChild ? Slot : "button";

  return (
    <Comp
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  );
}

// NavButton Component with Toggle Animation
interface NavButtonProps {
  isActive: boolean;
  setIsActive: (isActive: boolean) => void;
  menuBgColor?: string;
  menuBgImage?: string;
}

export function NavButton({ isActive, setIsActive, menuBgColor, menuBgImage }: NavButtonProps) {
  return (
    <div
        onClick={() => setIsActive(!isActive)}
        className="fixed top-0 right-0 h-8 w-20 rounded-full cursor-pointer overflow-hidden"
    >
        {/* Slider Container */}
        <motion.div
            className="relative w-full h-full text-xs font-semibold text-black"
            animate={{ top: isActive ? '-100%' : '0%' }}
            transition={{ duration: 0.4, ease: [0.76, 0, 0.24, 1] }}
        >
            {/* Menu Button */}
            <div className="h-full w-full flex items-center justify-center uppercase"
                style={{ backgroundColor: menuBgColor || '', backgroundImage: menuBgImage ? `url(${menuBgImage})` : 'none'   }}
            >
                <p>Menu</p>
            </div>

            {/* Close Button */}
            <div className="absolute top-full h-full w-full bg-black text-white flex items-center justify-center uppercase">
                <p>Close</p>
            </div>
        </motion.div>
    </div>
);
}

export default { Button, NavButton };

import { motion } from "framer-motion";
import Link from "next/link";

interface NavProps {
    links?: { title: string, href: string }[];
    footerLinks?: { title: string, href: string }[];
}

const perspective = {
    initial: {
        opacity: 0,
        rotateX: 90,
        translateY: 0,
        translateX: -20,
    },
    enter: ({ index }: { index: number }) => ({
        opacity: 1,
        rotateX: 0,
        translateY: 0,
        translateX: 0,
        transition: {
            duration: 0.6,
            opacity: { duration: 0.2 },
            delay: 0.1 + index * 0.11,
            ease: [0.215, 0.61, 0.355, 1],
        },
    }),
    exit: {
        opacity: 0,
        transition: {
            duration: 0.5,
            ease: [0.76, 0, 0.24, 1],
        },
    },
};

const footerAnimation = {
    initial: {
        opacity: 0,
        translateY: 10,
    },
    enter: ({ index }: { index: number }) => ({
        opacity: 1,
        translateY: 0,
        transition: {
            duration: 0.4,
            delay: 0.6 + index * 0.1, // Footer links will start appearing after sidebar links are done
            ease: [0.215, 0.61, 0.355, 1],
        },
    }),
    exit: {
        opacity: 0,
        translateY: 10,
        transition: {
            duration: 0.3,
            ease: [0.76, 0, 0.24, 1],
        },
    },
};

export default function Nav({ links, footerLinks }: NavProps) {
    return (
        <div className="text-black font-medium uppercase flex flex-col gap-12 justify-between h-full px-8 pt-20 pb-10 box-border rounded-2xl">
            <div className="flex flex-col space-y-4 text-5xl">
                {links?.map((link, index) => (
                    <div key={index} style={{ perspective: "120px", perspectiveOrigin: "right" }}>
                        <motion.div
                            custom={{ index }}
                            variants={perspective}
                            initial="initial"
                            animate="enter"
                            exit="exit"
                        >
                            <Link href={link.href} className="flex items-center hover:border-l-3 border-black transition-all duration-75">
                                <div className="hover:pl-2 transition-all duration-150 scroll-smooth ease-linear">
                                {link.title}
                                </div>
                                </Link>
                        </motion.div>
                    </div>
                ))}
            </div>

            <div className="flex justify-between text-xs">
                {footerLinks?.map((link, index) => (
                    <motion.div
                        key={index}
                        custom={{ index }}
                        variants={footerAnimation}
                        initial="initial"
                        animate="enter"
                        exit="exit"
                    >
                        <Link href={link.href}>{link.title}</Link>
                    </motion.div>
                ))}
            </div>
        </div>
    );
}
